window.ZT_COMMON={zh:{navHome:'首页',navTools:'工具箱',navAll:'全部工具',navPdf:'PDF 工具',navArticles:'教程中心',navCategories:'工具分类',navAbout:'关于',navContact:'联系我们',navPrivacy:'隐私政策',navGuides:'深度指南',navCompare:'工具对比',navProfessions:'职业工具',navMy:'用户中心',navFAQ:'常见问题',footerCopy:'© 2026 ZenTools. 免费在线工具箱，持续更新中。',searchPlaceholder:'搜索工具，例如：PDF、图片压缩、AI 写作...',breadcrumbHome:'首页',langZh:'中文',langEn:'英语',langJa:'日语',langVi:'越南语'},en:{navHome:'Home',navTools:'Tools',navAll:'All Tools',navPdf:'PDF Tools',navArticles:'Guides',navCategories:'Categories',navAbout:'About',navContact:'Contact',navPrivacy:'Privacy',navGuides:'Deep Guides',navCompare:'Compare',navProfessions:'By Profession',navMy:'My Space',navFAQ:'FAQ',footerCopy:'© 2026 ZenTools. Free online toolbox,continuously updated.',searchPlaceholder:'Search tools,e.g. PDF,image compress,AI writing...',breadcrumbHome:'Home',langZh:'Chinese',langEn:'English',langJa:'Japanese',langVi:'Vietnamese'},ja:{navHome:'ホーム',navTools:'ツール',navAll:'すべてのツール',navPdf:'PDF ツール',navArticles:'ガイド',navCategories:'カテゴリー',navAbout:'概要',navContact:'お問い合わせ',navPrivacy:'プライバシー',navGuides:'深層ガイド',navCompare:'ツール比較',navProfessions:'職業別ツール',navMy:'マイスペース',navFAQ:'よくある質問',footerCopy:'© 2026 ZenTools. 無料オンラインツールボックス、随時更新中。',searchPlaceholder:'ツールを検索（例：PDF、画像圧縮、AI 作成...）',breadcrumbHome:'ホーム',langZh:'中国語',langEn:'英語',langJa:'日本語',langVi:'ベトナム語'},vi:{navHome:'Trang chủ',navTools:'Công cụ',navAll:'Tất cả công cụ',navPdf:'Công cụ PDF',navArticles:'Hướng dẫn',navCategories:'Danh mục',navAbout:'Giới thiệu',navContact:'Liên hệ',navPrivacy:'Riêng tư',navGuides:'Hướng dẫn chuyên sâu',navCompare:'So sánh',navProfessions:'Theo Nghề',navMy:'Trang cá nhân',navFAQ:'FAQ',footerCopy:'© 2026 ZenTools. Hộp công cụ trực tuyến miễn phí,liên tục cập nhật.',searchPlaceholder:'Tìm công cụ,vd:PDF,nén ảnh,AI viết...',breadcrumbHome:'Trang chủ',langZh:'Tiếng Trung',langEn:'Tiếng Anh',langJa:'Tiếng Nhật',langVi:'Tiếng Việt'}};
function applyLanguage(lang){
  const currentLang = lang || localStorage.getItem('zentools_lang') || (navigator.language && navigator.language.slice(0,2)) || 'zh';
  // 合并翻译数据源：优先 ZT_PAGE（页面特定），然后 ZT_COMMON（公共）
  const pageDict = (window.ZT_PAGE && window.ZT_PAGE[currentLang]) || {};
  const commonDict = (window.ZT_COMMON && window.ZT_COMMON[currentLang]) || {};
  const dict = Object.assign({}, commonDict, pageDict);
  
  // 处理 data-i18n（从合并后的字典取翻译）
  document.querySelectorAll('[data-i18n]').forEach(function(elem){
    const key = elem.getAttribute('data-i18n');
    if(dict[key]){
      if(key === 'pageTitle'){
        document.title = dict[key];
      } else {
        elem.textContent = dict[key];
      }
    }
  });
  
  // 处理 data-i18n-page（兼容旧写法，从 ZT_PAGE 取翻译）
  if(window.ZT_PAGE && window.ZT_PAGE[currentLang]){
    document.querySelectorAll('[data-i18n-page]').forEach(function(elem){
      const key = elem.getAttribute('data-i18n-page');
      if(window.ZT_PAGE[currentLang][key]){
        elem.textContent = window.ZT_PAGE[currentLang][key];
      }
    });
  }
  
  // 处理 placeholder
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function(elem){
    const key = elem.getAttribute('data-i18n-placeholder');
    if(dict[key]){
      elem.placeholder = dict[key];
    }
  });
  
  // 更新 html lang 属性
  document.documentElement.lang = currentLang;
  
  // 触发自定义事件
  window.dispatchEvent(new CustomEvent('zt-langchange',{detail:{lang:currentLang}}));
}

// 监听 zt-setlang 事件（外部触发语言切换）
window.addEventListener('zt-setlang',function(e){
  if(e.detail && e.detail.lang){
    localStorage.setItem('zentools_lang', e.detail.lang);
    applyLanguage(e.detail.lang);
    // 同步所有语言选择器
    document.querySelectorAll('#langSelect, #langSelectMobile').forEach(function(s){
      s.value = e.detail.lang;
    });
  }
});

// 语言选择器 change 事件监听
function bindLangSelect(){
  document.querySelectorAll('#langSelect, #langSelectMobile').forEach(function(select){
    select.addEventListener('change', function(){
      const lang = this.value;
      localStorage.setItem('zentools_lang', lang);
      applyLanguage(lang);
      // 同步其他语言选择器
      document.querySelectorAll('#langSelect, #langSelectMobile').forEach(function(s){
        if(s !== this) s.value = lang;
      });
    });
  });
}

// DOMContentLoaded 时初始化
document.addEventListener('DOMContentLoaded', function(){
  const savedLang = localStorage.getItem('zentools_lang') || 'zh';
  // 设置所有语言选择器的初始值
  document.querySelectorAll('#langSelect, #langSelectMobile').forEach(function(s){
    s.value = savedLang;
  });
  bindLangSelect();
  applyLanguage(savedLang);
});

// 如果 DOM 已经加载完成，立即执行
if(document.readyState !== 'loading'){
  const savedLang = localStorage.getItem('zentools_lang') || 'zh';
  document.querySelectorAll('#langSelect, #langSelectMobile').forEach(function(s){
    s.value = savedLang;
  });
  bindLangSelect();
  applyLanguage(savedLang);
}
